   {{ $tool.parameters.competitors }}
Disapprove to replace them; then type the list you want.

parameters.jsCode:
let raw = query;
if (raw && typeof raw === "object" && raw.input !== undefined) raw = raw.input;
let input;
try {
  input = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (e) {
  return "ERROR: input is not valid JSON. Send one JSON object with the fields target, rows and previous_rows.";
}
if (!input || typeof input !== "object") return "ERROR: input is empty. Send one JSON object with the fields target, rows and previous_rows.";

const scope = ["GB300", "GB200", "B300", "B200", "H200", "H100", "BLENDED"];
function scopeGpu(g) {
  const u = String(g || "").toUpperCase();
  if (u.indexOf("GH200") >= 0) return null;
  for (let i = 0; i < scope.length; i++) { if (u.indexOf(scope[i]) >= 0) return scope[i] === "BLENDED" ? "blended" : scope[i]; }
  return null;
}
const bounds = { H100: [1, 12], H200: [1.2, 15], B200: [1.5, 20], B300: [2, 25], GB200: [3, 30], GB300: [3, 30] };
const aliases = { nbis: "nebius", crwv: "coreweave", iren: "iren", lambda: "lambda" };
let target = String(input.target || "").toLowerCase().trim();
if (aliases[target]) target = aliases[target];

const rows = [];
(Array.isArray(input.rows) ? input.rows : []).forEach(function (r) {
  const g = scopeGpu(r.gpu);
  if (g) rows.push(Object.assign({}, r, { gpu: g }));
});

let prevRaw = input.previous_rows;
if (typeof prevRaw === "string") { try { const p = JSON.parse(prevRaw); if (Array.isArray(p)) prevRaw = p; } catch (e) {} }
const prev = [];
if (Array.isArray(prevRaw)) {
  prevRaw.forEach(function (q) { if (q && typeof q.per_gpu_hour === "number") prev.push(q); });
} else if (typeof prevRaw === "string") {
  prevRaw.split(";").forEach(function (part) {
    const f = part.trim().split("|");
    if (f.length >= 4 && !isNaN(parseFloat(f[3]))) prev.push({ provider: f[0].trim(), gpu: f[1].trim(), price_type: f[2].trim(), per_gpu_hour: parseFloat(f[3]) });
  });
}

function round(x) { return Math.round(x * 100) / 100; }
function sign(x) { return x >= 0 ? "+" : ""; }
function key(r) { return r.gpu + "|" + r.price_type; }
const rank = { provider: 0, filing: 1, tracker: 2, blog: 3 };
function rk(k) { return rank[k] === undefined ? 4 : rank[k]; }
function isTarget(p) { const x = String(p || "").toLowerCase(); return x.length > 0 && target.length > 0 && (target.indexOf(x) >= 0 || x.indexOf(target) >= 0); }
function addStatus(out, text) { out.status = out.status ? out.status + "; " + text : text; }

const normalized = rows.map(function (r) {
  const out = Object.assign({}, r, { per_gpu_hour: null, status: "", implausible: false });
  const note = String(r.note || "");
  if (r.price_usd === null && /not offered/i.test(note)) { out.status = "not offered"; return out; }
  if (r.unit === "per_gpu_hour" && typeof r.price_usd === "number") {
    if (r.price_usd > 15 && r.gpus_per_node > 1) {
      out.per_gpu_hour = round(r.price_usd / r.gpus_per_node);
      out.status = "assumed node price: $" + r.price_usd + " / " + r.gpus_per_node + " GPUs";
    } else out.per_gpu_hour = round(r.price_usd);
  } else if (r.unit === "per_node_hour" && typeof r.price_usd === "number") {
    if (r.gpus_per_node > 0) out.per_gpu_hour = round(r.price_usd / r.gpus_per_node);
    else out.status = "cannot normalize: GPUs per node missing";
  } else if (r.unit === "arr_disclosure") {
    if (r.arr_usd > 0 && r.gpu_count > 0) {
      out.per_gpu_hour = round(r.arr_usd / r.gpu_count / 8760);
      out.status = "implied: $" + r.arr_usd + " / " + r.gpu_count + " GPUs / 8,760 h";
    } else out.status = "cannot derive: ARR or GPU count missing";
  } else if (r.price_usd === null) {
    out.status = /contact/i.test(note) ? "contact sales" : "not found";
  }
  if (/\/(blog|news|newsroom|press)\//i.test(String(r.source_url || ""))) {
    out.source_kind = "blog";
    addStatus(out, "blog/news source, verify");
  }
  const b = bounds[out.gpu];
  if (out.per_gpu_hour !== null && b && out.price_type !== "implied_contract") {
    const low = out.price_type === "spot" ? b[0] * 0.6 : b[0];
    if (out.per_gpu_hour < low || out.per_gpu_hour > b[1]) {
      out.implausible = true;
      addStatus(out, "implausible price, excluded");
    }
  }
  return out;
});

const best = {};
const conflicts = [];
normalized.filter(function (x) { return x.per_gpu_hour !== null && !x.implausible; }).forEach(function (r) {
  const k = r.provider + "|" + key(r);
  const cur = best[k];
  if (!cur) { best[k] = r; return; }
  if (Math.abs(cur.per_gpu_hour - r.per_gpu_hour) > 0.01) {
    conflicts.push(r.provider + " " + r.gpu + " " + r.price_type + ": $" + cur.per_gpu_hour + " (" + cur.source_url + ") vs $" + r.per_gpu_hour + " (" + r.source_url + ")");
  }
  if (rk(r.source_kind) < rk(cur.source_kind)) best[k] = r;
});
const bestRows = Object.values(best);

const gaps = [];
bestRows.filter(function (t) { return isTarget(t.provider); }).forEach(function (t) {
  bestRows.filter(function (c) { return !isTarget(c.provider) && key(c) === key(t); }).forEach(function (c) {
    const d = round(c.per_gpu_hour - t.per_gpu_hour);
    const pct = t.per_gpu_hour ? round(d / t.per_gpu_hour * 100) : null;
    const flag = c.source_kind === "blog" || t.source_kind === "blog" ? " [blog/news source, verify]" : "";
    gaps.push(t.gpu + " " + t.price_type + ": " + c.provider + " $" + c.per_gpu_hour + " vs " + t.provider + " $" + t.per_gpu_hour + " = " + sign(d) + "$" + d + " per GPU-hour (" + (pct === null ? "n/a" : sign(pct) + pct + "%") + ")" + flag);
  });
});

const changes = [];
bestRows.forEach(function (r) {
  const p = prev.find(function (q) { return q.provider === r.provider && key(q) === key(r); });
  if (p && Math.abs(p.per_gpu_hour - r.per_gpu_hour) > 0.01) {
    const d = round(r.per_gpu_hour - p.per_gpu_hour);
    changes.push(r.provider + " " + r.gpu + " " + r.price_type + ": $" + p.per_gpu_hour + " -> $" + r.per_gpu_hour + " (" + sign(d) + "$" + d + ")");
  }
});

const table = normalized.map(function (r) {
  const price = r.per_gpu_hour !== null ? "$" + r.per_gpu_hour + (r.status ? " (" + r.status + ")" : "") : r.status;
  return r.provider + " | " + r.gpu + " | " + r.price_type + " | " + price + " | " + r.source_kind + " | " + r.source_url;
});
const prices_compact = bestRows.map(function (r) { return r.provider + "|" + r.gpu + "|" + r.price_type + "|" + r.per_gpu_hour; }).join("; ");

return JSON.stringify({ table: table, gaps: gaps, conflicts: conflicts, changes: changes, prices_compact: prices_compact });
